fn compound_order(page: *const page) -> u32 {
let folio: *const folio = page as *const folio;
if test_bit__5!(6i32, unsafe { core::ptr::addr_of!((*folio).__slate_anon_0.__slate_anon_0.flags.f) }) == 0 {
return 0;
}
folio_large_order(folio)
}

