fn within_module_mem_type(addr: u64, r#mod: *const module, r#type: i32) -> bool {
let base: u64 = (unsafe { (*((*r#mod).mem.as_ptr() as *const module_memory).wrapping_offset((r#type as i32) as isize)).base }) as u64;
let size: u64 = (unsafe { (*((*r#mod).mem.as_ptr() as *const module_memory).wrapping_offset((r#type as i32) as isize)).size }) as u64;
addr.wrapping_sub(base) < size
}

fn within_module_core(addr: u64, r#mod: *const module) -> bool {
let mut r#type: i32 = 0;
while (r#type as i32) < 7 {
if !mod_mem_type_is_init!(r#type) {
if within_module_mem_type(addr, r#mod, r#type) {
return true;
}
}
r#type = (r#type as i32).wrapping_add(1) as i32;
}
false
}

