fn is_kernel_core_data(addr: u64) -> bool {
if addr >= ((unsafe { core::ptr::addr_of_mut!(_sdata) as *mut u8 }) as u64) && addr < ((unsafe { core::ptr::addr_of_mut!(_edata) as *mut u8 }) as u64) {
return true;
}
if addr >= ((unsafe { core::ptr::addr_of_mut!(__bss_start) as *mut u8 }) as u64) && addr < ((unsafe { core::ptr::addr_of_mut!(__bss_stop) as *mut u8 }) as u64) {
return true;
}
false
}

fn is_kernel_rodata(addr: u64) -> bool {
addr >= ((unsafe { core::ptr::addr_of_mut!(__start_rodata) as *mut u8 }) as u64) && addr < ((unsafe { core::ptr::addr_of_mut!(__end_rodata) as *mut u8 }) as u64)
}

fn __is_kernel(addr: u64) -> bool {
addr >= ((unsafe { core::ptr::addr_of_mut!(_stext) as *mut u8 }) as u64) && addr < ((unsafe { core::ptr::addr_of_mut!(_end) as *mut u8 }) as u64) || addr >= ((unsafe { core::ptr::addr_of_mut!(__init_begin) as *mut u8 }) as u64) && addr < ((unsafe { core::ptr::addr_of_mut!(__init_end) as *mut u8 }) as u64)
}

