fn tracing_generic_entry_update(entry: *mut trace_entry, r#type: u16, trace_ctx: u32) {
unsafe {
(*entry).preempt_count = (trace_ctx & 255) as u8;
}
unsafe {
(*entry).pid = (*get_current()).pid;
}
unsafe {
(*entry).r#type = r#type;
}
unsafe {
(*entry).flags = (trace_ctx >> 16i32) as u8;
}
}

fn tracing_gen_ctx_flags(irqflags: u64) -> u32 {
let irq_status: u32 = (if irqs_disabled_flags!(irqflags) != 0 { 1i32 } else { 0i32 }) as u32;
tracing_gen_ctx_irq_test(irq_status)
}

fn tracing_gen_ctx() -> u32 {
let mut irqflags: u64 = 0;
local_save_flags!(irqflags);
tracing_gen_ctx_flags(irqflags)
}

